def main():
    N = int(input())
    intervals = []

    for _ in range(N):
        start, end = map(int, input().split())
        intervals.append((start, end))

    intervals.sort()

    n_intersecting_pairs = 0

    for i in range(N):
        for j in range(i + 1, N):
            if intervals[j][0] <= intervals[i][1]:
                n_intersecting_pairs += 1

    print(n_intersecting_pairs)
